panel.add(ui.Label('Red: native NaN pixels. Orange: affected 500 m model cells. Cyan: padded model extent. Toggle comparison layers in Layers.'));
var status=ui.Label();var pick=ui.Select({items:Object.keys(CASES),value:'G057_2013',onChange:render});panel.add(pick);panel.add(status);
panel.add(ui.Label('MapBiomas legend: 3 forest; 4 savanna/open woodland; 6 flooded forest; 7 flooded savanna; 11 wetland; 12 grassland; 15 pasture; 33 water. Other classes gray.'));
